import type { Board } from './model.ts'

export const SUPPORTED_SIZES = [4, 6, 8, 10, 12, 14, 16] as const
export const MAX_SEED = 2_147_483_646
const PARK_MILLER_MODULUS = 2_147_483_647
const PARK_MILLER_MULTIPLIER = 16_807
const GENERATOR_RANGE = 2_147_483_646

export type BoardSize = (typeof SUPPORTED_SIZES)[number]

export function isBoardSize(value: unknown): value is BoardSize {
  return typeof value === 'number' && SUPPORTED_SIZES.some((size) => size === value)
}

export function parseBoardCode(code: string): Board | null {
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/u.exec(code)
  if (!match || match[0] !== code) return null
  const size = Number(match[1])
  const seed = Number(match[2])
  if (!isBoardSize(size) || !Number.isSafeInteger(seed) || seed > MAX_SEED) return null
  return Object.freeze({ code, size, seed })
}

function draw(state: { value: number }, bound: number): number {
  const limit = Math.floor(GENERATOR_RANGE / bound) * bound
  while (true) {
    state.value = (state.value * PARK_MILLER_MULTIPLIER) % PARK_MILLER_MODULUS
    const sample = state.value - 1
    if (sample < limit) return sample % bound
  }
}

export function createDeck(boardCode: string): readonly number[] | null {
  const board = parseBoardCode(boardCode)
  if (!board) return null
  const deck = Array.from({ length: board.size * board.size }, (_, index) => Math.floor(index / 2))
  const generator = { value: board.seed }
  for (let index = deck.length - 1; index > 0; index -= 1) {
    const other = draw(generator, index + 1)
    const current = deck[index]
    const swapped = deck[other]
    if (current === undefined || swapped === undefined) return null
    deck[index] = swapped
    deck[other] = current
  }
  return Object.freeze(deck)
}
import { createDeck, parseBoardCode } from './board.ts'
import {
  CLOSED_SELECTION,
  GameState,
  MAX_ELAPSED_MS,
  MAX_MOVES,
  MISMATCH_MS,
  SELECTION_KIND,
  Selection,
  freezeState,
} from './model.ts'

export function createGame(boardCode: string): GameState | null {
  const board = parseBoardCode(boardCode)
  const deck = createDeck(boardCode)
  if (!board || !deck) return null
  return freezeState({
    board,
    deck,
    matched: [],
    selection: CLOSED_SELECTION,
    moves: 0,
    elapsedMs: 0,
    started: false,
  })
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.deck.length
}

function nextSelection(state: GameState, selection: Selection): GameState {
  return freezeState({ ...state, selection })
}

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isInteger(index) || index < 0 || index >= state.deck.length || isWon(state)) return state
  if (state.matched.includes(index) || state.selection.kind === SELECTION_KIND.mismatch) return state
  if (state.selection.kind === SELECTION_KIND.closed) {
    return freezeState({ ...state, selection: { kind: SELECTION_KIND.one, index }, started: true })
  }
  if (state.selection.index === index) return state
  const firstFace = state.deck[state.selection.index]
  const nextFace = state.deck[index]
  const moves = Math.min(MAX_MOVES, state.moves + 1)
  if (firstFace !== undefined && firstFace === nextFace) {
    return freezeState({
      ...state,
      matched: [...state.matched, state.selection.index, index],
      selection: CLOSED_SELECTION,
      moves,
    })
  }
  return freezeState({
    ...state,
    selection: { kind: SELECTION_KIND.mismatch, first: state.selection.index, second: index, remainingMs: MISMATCH_MS },
    moves,
  })
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isSafeInteger(milliseconds) || milliseconds <= 0 || isWon(state)) return state
  const elapsedMs = state.started
    ? state.elapsedMs + Math.min(milliseconds, MAX_ELAPSED_MS - state.elapsedMs)
    : state.elapsedMs
  if (state.selection.kind !== SELECTION_KIND.mismatch) {
    return elapsedMs === state.elapsedMs ? state : freezeState({ ...state, elapsedMs })
  }
  const remainingMs = state.selection.remainingMs - milliseconds
  if (remainingMs <= 0) return freezeState({ ...state, elapsedMs, selection: CLOSED_SELECTION })
  return freezeState({ ...state, elapsedMs, selection: { ...state.selection, remainingMs } })
}

export function formatElapsed(elapsedMs: number): string {
  const seconds = Math.floor(elapsedMs / 1_000)
  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`
}
export const SELECTION_KIND = {
  closed: 'closed',
  one: 'one',
  mismatch: 'mismatch',
} as const

export type Selection =
  | { readonly kind: typeof SELECTION_KIND.closed }
  | { readonly kind: typeof SELECTION_KIND.one; readonly index: number }
  | {
      readonly kind: typeof SELECTION_KIND.mismatch
      readonly first: number
      readonly second: number
      readonly remainingMs: number
    }

export interface Board {
  readonly code: string
  readonly size: number
  readonly seed: number
}

export interface GameState {
  readonly board: Board
  readonly deck: readonly number[]
  readonly matched: readonly number[]
  readonly selection: Selection
  readonly moves: number
  readonly elapsedMs: number
  readonly started: boolean
}

export const SNAPSHOT_VERSION = 1
export const REPLAY_VERSION = 1
export const MISMATCH_MS = 800
export const MAX_MOVES = 999_999
export const MAX_ELAPSED_MS = 359_999_999
export const SNAPSHOT_MAX_BYTES = 65_536
export const REPLAY_MAX_BYTES = 1_048_576
export const REPLAY_MAX_ACTIONS = 10_000

export const CLOSED_SELECTION: Selection = Object.freeze({ kind: SELECTION_KIND.closed })

export function freezeState(state: GameState): GameState {
  return Object.freeze({
    ...state,
    board: Object.freeze({ ...state.board }),
    deck: Object.freeze([...state.deck]),
    matched: Object.freeze([...state.matched]),
    selection: Object.freeze({ ...state.selection }),
  })
}

import { createGame } from './game.ts'
import type { GameState, Selection } from './model.ts'
import {
  MAX_ELAPSED_MS,
  MAX_MOVES,
  MISMATCH_MS,
  SELECTION_KIND,
  SNAPSHOT_MAX_BYTES,
  SNAPSHOT_VERSION,
  freezeState,
} from './model.ts'

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function hasKeys(value: Record<string, unknown>, expected: readonly string[]): boolean {
  const keys = Object.keys(value)
  return keys.length === expected.length && expected.every((key) => Object.hasOwn(value, key))
}

function isNonnegativeSafeInteger(value: unknown): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0
}

function decodeSelection(value: unknown, state: GameState, matched: ReadonlySet<number>): Selection | null {
  if (!isRecord(value) || typeof value.kind !== 'string') return null
  if (value.kind === SELECTION_KIND.closed) {
    return hasKeys(value, ['kind']) ? { kind: SELECTION_KIND.closed } : null
  }
  if (value.kind === SELECTION_KIND.one) {
    if (!hasKeys(value, ['kind', 'index'])) return null
    if (!isNonnegativeSafeInteger(value.index) || value.index >= state.deck.length || matched.has(value.index)) return null
    return { kind: SELECTION_KIND.one, index: value.index }
  }
  if (value.kind === SELECTION_KIND.mismatch) {
    if (!hasKeys(value, ['kind', 'first', 'second', 'remainingMs'])) return null
    const { first, second, remainingMs } = value
    if (!isNonnegativeSafeInteger(first) || !isNonnegativeSafeInteger(second)) return null
    if (first >= state.deck.length || second >= state.deck.length || first === second) return null
    if (matched.has(first) || matched.has(second)) return null
    if (state.deck[first] === state.deck[second]) return null
    if (!isNonnegativeSafeInteger(remainingMs) || remainingMs < 1 || remainingMs > MISMATCH_MS) return null
    return { kind: SELECTION_KIND.mismatch, first, second, remainingMs }
  }
  return null
}

export function decodeSnapshot(text: string): GameState | null {
  if (new TextEncoder().encode(text).byteLength > SNAPSHOT_MAX_BYTES) return null
  let parsed: unknown
  try {
    parsed = JSON.parse(text)
  } catch {
    return null
  }
  if (!isRecord(parsed) || !hasKeys(parsed, ['version', 'boardCode', 'matched', 'selection', 'moves', 'elapsedMs', 'started'])) return null
  if (parsed.version !== SNAPSHOT_VERSION || typeof parsed.boardCode !== 'string' || !Array.isArray(parsed.matched)) return null
  if (!isNonnegativeSafeInteger(parsed.moves) || parsed.moves > MAX_MOVES) return null
  if (!isNonnegativeSafeInteger(parsed.elapsedMs) || parsed.elapsedMs > MAX_ELAPSED_MS) return null
  if (typeof parsed.started !== 'boolean') return null
  const initial = createGame(parsed.boardCode)
  if (!initial) return null
  const matched: number[] = []
  const matchedSet = new Set<number>()
  for (const index of parsed.matched) {
    if (!isNonnegativeSafeInteger(index) || index >= initial.deck.length || matchedSet.has(index)) return null
    matched.push(index)
    matchedSet.add(index)
  }
  const faceCounts = new Map<number, number>()
  for (const index of matched) {
    const face = initial.deck[index]
    if (face === undefined) return null
    faceCounts.set(face, (faceCounts.get(face) ?? 0) + 1)
  }
  if ([...faceCounts.values()].some((count) => count !== 2)) return null
  const candidate = { ...initial, matched, moves: parsed.moves, elapsedMs: parsed.elapsedMs, started: parsed.started }
  const selection = decodeSelection(parsed.selection, candidate, matchedSet)
  if (!selection) return null
  const pairCount = matched.length / 2
  const requiredMoves = pairCount + (selection.kind === SELECTION_KIND.mismatch ? 1 : 0)
  if (parsed.moves < requiredMoves) return null
  if (!parsed.started && (parsed.moves !== 0 || parsed.elapsedMs !== 0 || matched.length !== 0 || selection.kind !== SELECTION_KIND.closed)) return null
  if (parsed.started && parsed.moves === 0 && selection.kind !== SELECTION_KIND.one) return null
  if (matched.length === initial.deck.length && selection.kind !== SELECTION_KIND.closed) return null
  return freezeState({ ...candidate, selection })
}

export function encodeSnapshot(state: GameState): string {
  return JSON.stringify({
    version: SNAPSHOT_VERSION,
    boardCode: state.board.code,
    matched: state.matched,
    selection: state.selection,
    moves: state.moves,
    elapsedMs: state.elapsedMs,
    started: state.started,
  }, null, 2)
}
import { createGame, activateCard, advanceGame } from './game.ts'
import type { GameState } from './model.ts'
import {
  REPLAY_MAX_ACTIONS,
  REPLAY_MAX_BYTES,
  REPLAY_VERSION,
} from './model.ts'

interface ReplayAction {
  readonly atMs: number
  readonly index: number
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function exactKeys(value: Record<string, unknown>, keys: readonly string[]): boolean {
  return Object.keys(value).length === keys.length && keys.every((key) => Object.hasOwn(value, key))
}

function isTimestamp(value: unknown): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0
}

function parseReplay(text: string): { boardCode: string; actions: ReplayAction[]; endMs: number } | null {
  if (new TextEncoder().encode(text).byteLength > REPLAY_MAX_BYTES) return null
  let parsed: unknown
  try {
    parsed = JSON.parse(text)
  } catch {
    return null
  }
  if (!isRecord(parsed) || !exactKeys(parsed, ['version', 'boardCode', 'actions', 'endMs'])) return null
  if (parsed.version !== REPLAY_VERSION || typeof parsed.boardCode !== 'string') return null
  if (!Array.isArray(parsed.actions) || parsed.actions.length > REPLAY_MAX_ACTIONS || !isTimestamp(parsed.endMs)) return null
  const actions: ReplayAction[] = []
  let previous = 0
  for (const value of parsed.actions) {
    if (!isRecord(value) || !exactKeys(value, ['atMs', 'index'])) return null
    if (!isTimestamp(value.atMs) || !isTimestamp(value.index) || value.atMs < previous) return null
    actions.push({ atMs: value.atMs, index: value.index })
    previous = value.atMs
  }
  if (parsed.endMs < previous) return null
  return { boardCode: parsed.boardCode, actions, endMs: parsed.endMs }
}

export function replayGame(text: string): GameState | null {
  const replay = parseReplay(text)
  if (!replay) return null
  let state = createGame(replay.boardCode)
  if (!state) return null
  let timeline = 0
  for (const action of replay.actions) {
    state = advanceGame(state, action.atMs - timeline)
    if (action.index >= state.deck.length) return null
    state = activateCard(state, action.index)
    timeline = action.atMs
  }
  state = advanceGame(state, replay.endMs - timeline)
  return state
}
import { readFile } from 'node:fs/promises'
import { replayGame } from '../src/game/replay.ts'
import { encodeSnapshot } from '../src/game/snapshot.ts'

const path = process.argv[2]

if (!path) {
  process.stderr.write('Invalid replay.\n')
  process.exitCode = 1
} else {
  try {
    const text = await readFile(path, 'utf8')
    const state = replayGame(text)
    if (!state) {
      process.stderr.write('Invalid replay.\n')
      process.exitCode = 1
    } else {
      process.stdout.write(`${encodeSnapshot(state)}\n`)
    }
  } catch {
    process.stderr.write('Invalid replay.\n')
    process.exitCode = 1
  }
}

import { describe, expect, it } from 'vitest'
import { createDeck, parseBoardCode, SUPPORTED_SIZES } from './board.ts'

describe('board codes and deterministic decks', () => {
  it('matches the published version 1 deck vector', () => {
    expect(createDeck('np1-4-1')).toEqual([6, 7, 0, 5, 2, 2, 0, 5, 3, 7, 1, 6, 4, 4, 1, 3])
  })

  it('uses a reproducible deal with every face exactly twice at each size', () => {
    for (const size of SUPPORTED_SIZES) {
      const first = createDeck(`np1-${size}-2147483646`)
      const second = createDeck(`np1-${size}-2147483646`)
      expect(second).toEqual(first)
      const counts = new Map<number, number>()
      for (const face of first ?? []) counts.set(face, (counts.get(face) ?? 0) + 1)
      expect(counts.size).toBe((size * size) / 2)
      expect([...counts.values()].every((count) => count === 2)).toBe(true)
    }
  })

  it('accepts only the exact supported board code syntax', () => {
    expect(parseBoardCode('np1-4-1')).toEqual({ code: 'np1-4-1', size: 4, seed: 1 })
    for (const code of [
      'np1-4-0', 'np1-4-01', 'np1-5-1', 'np1-4-2147483647',
      'np1-4-1 ', ' np1-4-1', 'np1-4-1\n', 'NP1-4-1', 'np1-4-1x',
    ]) {
      expect(parseBoardCode(code), code).toBeNull()
    }
  })
})
import { describe, expect, it } from 'vitest'
import { activateCard, advanceGame, createGame, formatElapsed, isWon } from './game.ts'
import { SELECTION_KIND } from './model.ts'

describe('game transitions and logical time', () => {
  it('reveals one card without a move, including repeated selection', () => {
    const initial = createGame('np1-4-1')
    if (!initial) throw new Error('fixture board is invalid')
    const first = activateCard(initial, 0)
    expect(first.selection).toEqual({ kind: SELECTION_KIND.one, index: 0 })
    expect(first.started).toBe(true)
    expect(first.moves).toBe(0)
    expect(activateCard(first, 0)).toBe(first)
  })

  it('keeps matches and waits exactly 800ms before closing misses', () => {
    const initial = createGame('np1-4-1')
    if (!initial) throw new Error('fixture board is invalid')
    const match = activateCard(activateCard(initial, 4), 5)
    expect(match.matched).toEqual([4, 5])
    expect(match.moves).toBe(1)
    expect(isWon(match)).toBe(false)
    let miss = activateCard(activateCard(match, 0), 1)
    expect(miss.moves).toBe(2)
    expect(activateCard(miss, 2)).toBe(miss)
    miss = advanceGame(miss, 799)
    expect(miss.selection).toMatchObject({ kind: SELECTION_KIND.mismatch, remainingMs: 1 })
    miss = advanceGame(miss, 1)
    expect(miss.selection).toEqual({ kind: SELECTION_KIND.closed })
    expect(miss.elapsedMs).toBe(800)
  })

  it('advances a mismatch after the elapsed clock is capped', () => {
    const initial = createGame('np1-4-1')
    if (!initial) throw new Error('fixture board is invalid')
    const miss = activateCard(activateCard(initial, 0), 1)
    const capped = { ...miss, elapsedMs: 359_999_999 }
    const resolved = advanceGame(capped, 800)
    expect(resolved.elapsedMs).toBe(359_999_999)
    expect(resolved.selection).toEqual({ kind: SELECTION_KIND.closed })
  })

  it('formats elapsed time with unbounded minutes and rounded-down seconds', () => {
    expect(formatElapsed(3_600_999)).toBe('60:00')
    expect(formatElapsed(123_000)).toBe('2:03')
  })
})

import { describe, expect, it } from 'vitest'
import { SELECTION_KIND } from './model.ts'
import { replayGame } from './replay.ts'

describe('version 1 replay', () => {
  it('replays the published match example into the expected final snapshot', () => {
    const replay = JSON.stringify({ version: 1, boardCode: 'np1-4-1', actions: [{ atMs: 0, index: 0 }, { atMs: 0, index: 11 }], endMs: 800 })
    expect(replayGame(replay)).toMatchObject({ matched: [0, 11], moves: 1, elapsedMs: 800, started: true })
  })

  it('resolves a mismatch exactly at an action time before activating that card', () => {
    const replay = JSON.stringify({
      version: 1,
      boardCode: 'np1-4-1',
      actions: [{ atMs: 0, index: 0 }, { atMs: 0, index: 1 }, { atMs: 800, index: 1 }],
      endMs: 800,
    })
    expect(replayGame(replay)).toMatchObject({
      selection: { kind: SELECTION_KIND.one, index: 1 }, moves: 1, elapsedMs: 800,
    })
  })

  it('uses replay time for mismatches beyond the elapsed cap', () => {
    const replay = JSON.stringify({
      version: 1,
      boardCode: 'np1-4-1',
      actions: [{ atMs: 0, index: 0 }, { atMs: 0, index: 1 }],
      endMs: 359_999_999,
    })
    expect(replayGame(replay)).toMatchObject({ selection: { kind: SELECTION_KIND.closed }, elapsedMs: 359_999_999 })
  })

  it('supports safe integer timestamps and starts elapsed time at the first reveal', () => {
    const replay = JSON.stringify({
      version: 1,
      boardCode: 'np1-4-1',
      actions: [{ atMs: Number.MAX_SAFE_INTEGER - 10, index: 0 }, { atMs: Number.MAX_SAFE_INTEGER - 10, index: 1 }],
      endMs: Number.MAX_SAFE_INTEGER,
    })
    expect(replayGame(replay)).toMatchObject({ elapsedMs: 10, moves: 1 })
  })

  it('rejects malformed schemas, out-of-range positions and invalid timelines', () => {
    const base = { version: 1, boardCode: 'np1-4-1', actions: [{ atMs: 2, index: 0 }], endMs: 2 }
    expect(replayGame('{')).toBeNull()
    expect(replayGame(JSON.stringify({ ...base, extra: true }))).toBeNull()
    expect(replayGame(JSON.stringify({ ...base, endMs: 1 }))).toBeNull()
    expect(replayGame(JSON.stringify({ ...base, actions: [{ atMs: 3, index: 0 }, { atMs: 2, index: 1 }] }))).toBeNull()
    expect(replayGame(JSON.stringify({ ...base, actions: [{ atMs: 2, index: 16 }] }))).toBeNull()
    expect(replayGame(' '.repeat(1_048_577))).toBeNull()
  })
})
import { describe, expect, it } from 'vitest'
import { activateCard, createGame } from './game.ts'
import { decodeSnapshot, encodeSnapshot } from './snapshot.ts'

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function readObject(text: string): Record<string, unknown> {
  const value: unknown = JSON.parse(text)
  if (!isRecord(value)) throw new Error('fixture JSON is not an object')
  return value
}

function initialGame() {
  const state = createGame('np1-4-1')
  if (!state) throw new Error('fixture board is invalid')
  return state
}

describe('version 1 snapshots', () => {
  it('round trips game progress and exports only the specified fields', () => {
    const state = activateCard(activateCard(initialGame(), 0), 1)
    const text = encodeSnapshot(state)
    expect(Object.keys(readObject(text))).toEqual([
      'version', 'boardCode', 'matched', 'selection', 'moves', 'elapsedMs', 'started',
    ])
    expect(decodeSnapshot(text)).toEqual(state)
  })

  it('rejects malformed JSON, unknown keys, oversized UTF-8 and unsupported versions', () => {
    const valid = readObject(encodeSnapshot(initialGame()))
    expect(decodeSnapshot('{')).toBeNull()
    expect(decodeSnapshot(JSON.stringify({ ...valid, extra: true }))).toBeNull()
    expect(decodeSnapshot(JSON.stringify({ ...valid, version: 2 }))).toBeNull()
    expect(decodeSnapshot(' '.repeat(65_537))).toBeNull()
    expect(decodeSnapshot(`"${'é'.repeat(32_768)}"`)).toBeNull()
  })

  it('requires complete pairs, unique indices and enough moves', () => {
    const base = readObject(encodeSnapshot(initialGame()))
    expect(decodeSnapshot(JSON.stringify({ ...base, matched: [4] }))).toBeNull()
    expect(decodeSnapshot(JSON.stringify({ ...base, matched: [4, 5, 4] }))).toBeNull()
    expect(decodeSnapshot(JSON.stringify({ ...base, matched: [4, 5] }))).toBeNull()
  })

  it('validates selection shapes, mismatch timing and started-state consistency', () => {
    const initial = initialGame()
    const one = encodeSnapshot(activateCard(initial, 0))
    const oneData = readObject(one)
    const validMismatch = activateCard(activateCard(initial, 0), 1)
    const mismatch = readObject(encodeSnapshot(validMismatch))
    expect(decodeSnapshot(one)).not.toBeNull()
    expect(decodeSnapshot(JSON.stringify({ ...oneData, selection: { kind: 'one', index: 0, extra: 1 } }))).toBeNull()
    expect(decodeSnapshot(JSON.stringify({ ...oneData, selection: { kind: 'closed' } }))).toBeNull()
    expect(decodeSnapshot(JSON.stringify({ ...mismatch, selection: { kind: 'mismatch', first: 0, second: 1, remainingMs: 801 } }))).toBeNull()
    expect(decodeSnapshot(JSON.stringify({ ...mismatch, moves: 0 }))).toBeNull()
    expect(decodeSnapshot(JSON.stringify({ ...oneData, started: false }))).toBeNull()
  })

  it('accepts a valid matched pair in any position order', () => {
    const initial = initialGame()
    const matched = activateCard(activateCard(initial, 4), 5)
    const saved = readObject(encodeSnapshot(matched))
    expect(decodeSnapshot(JSON.stringify({ ...saved, matched: [5, 4] }))).not.toBeNull()
  })
})

import { MAX_MOVES } from '../model.ts'
import { isBoardSize, type BoardSize } from '../board.ts'

const PREFERENCE_KEY = 'neon-pairs.preferences.v1'
const BEST_KEY = 'neon-pairs.best.v1'
export type BestScores = Readonly<Partial<Record<BoardSize, number>>>

function record(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function readJson(key: string): unknown {
  try {
    const raw = window.localStorage.getItem(key)
    return raw === null ? null : JSON.parse(raw)
  } catch {
    return null
  }
}

export function readPreferredSize(): BoardSize {
  const value = readJson(PREFERENCE_KEY)
  return record(value) && isBoardSize(value.size) ? value.size : 4
}

export function savePreferredSize(size: BoardSize): void {
  try {
    window.localStorage.setItem(PREFERENCE_KEY, JSON.stringify({ size }))
  } catch {
    // Storage is optional; keep the current session playable.
  }
}

export function readBestScores(): BestScores {
  const value = readJson(BEST_KEY)
  if (!record(value)) return Object.freeze({})
  const scores: Partial<Record<BoardSize, number>> = {}
  for (const size of [4, 6, 8, 10, 12, 14, 16] as const) {
    const score = value[size]
    if (typeof score === 'number' && Number.isSafeInteger(score) && score >= 0 && score <= MAX_MOVES) {
      scores[size] = score
    }
  }
  return Object.freeze(scores)
}

export function recordBest(size: BoardSize, moves: number, previous: BestScores): BestScores {
  const current = previous[size]
  if (current !== undefined && current <= moves) return previous
  const next = Object.freeze({ ...previous, [size]: moves })
  try {
    window.localStorage.setItem(BEST_KEY, JSON.stringify(next))
  } catch {
    // Best scores never prevent play.
  }
  return next
}
import { useCallback, useEffect, useRef, useState } from 'react'

export function useAnnouncements(): { message: string; announce: (text: string) => void } {
  const [message, setMessage] = useState('')
  const queue = useRef<string[]>([])
  const timer = useRef<number | null>(null)

  const announce = useCallback((text: string) => {
    queue.current.push(text)
    if (timer.current !== null) return
    const showNext = (): void => {
      const next = queue.current.shift()
      if (next === undefined) { timer.current = null; return }
      setMessage('')
      timer.current = window.setTimeout(() => {
        setMessage(next)
        timer.current = window.setTimeout(() => {
          setMessage('')
          timer.current = window.setTimeout(showNext, 0)
        }, 700)
      }, 40)
    }
    showNext()
  }, [])

  useEffect(() => () => {
    if (timer.current !== null) window.clearTimeout(timer.current)
  }, [])

  return { message, announce }
}

import { useCallback, useEffect, useRef, useState } from 'react'
import { activateCard, advanceGame, createGame, formatElapsed, isWon } from '../game.ts'
import { isBoardSize, parseBoardCode, type BoardSize } from '../board.ts'
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts'
import type { GameState } from '../model.ts'
import { recordBest, readBestScores, readPreferredSize, savePreferredSize, type BestScores } from './storage.ts'
import { useAnnouncements } from './useAnnouncements.ts'

function newCode(size: BoardSize): string {
  const values = new Uint32Array(1)
  const seed = typeof crypto !== 'undefined'
    ? (crypto.getRandomValues(values), (values[0] ?? 0) % 2_147_483_646 + 1)
    : Math.floor(Math.random() * 2_147_483_646) + 1
  return `np1-${size}-${seed}`
}

function initialGame(): GameState {
  const size = readPreferredSize()
  const game = createGame(newCode(size))
  if (!game) throw new Error('Unable to create a supported board')
  return game
}

function pairAnnouncement(state: GameState): string {
  if (isWon(state)) return `Pair found. All pairs found in ${state.moves} moves and ${formatElapsed(state.elapsedMs)}.`
  const pairs = state.matched.length / 2
  return pairs === 1 ? 'Pair found. 1 pair matched.' : `Pair found. ${pairs} pairs matched.`
}

export interface Session {
  state: GameState
  bestScores: BestScores
  revision: number
  paused: boolean
  status: string
  announcement: string
  newGame(): void
  restart(): void
  chooseSize(size: BoardSize): void
  activate(index: number): void
  loadBoard(code: string): void
  importSnapshot(text: string): void
  exportSnapshot(): string
  resume(): void
  announce(text: string): void
}

export function useSession(): Session {
  const [state, setState] = useState(initialGame)
  const stateRef = useRef(state)
  const [bestScores, setBestScores] = useState<BestScores>(readBestScores)
  const [revision, setRevision] = useState(0)
  const [paused, setPaused] = useState(false)
  const pausedRef = useRef(false)
  const [status, setStatus] = useState('')
  const { message, announce, clear } = useAnnouncements()
  const bestAllowed = useRef(true)
  const lastTime = useRef(performance.now())
  const fraction = useRef(0)
  const clockRunning = useRef(false)

  const flushClock = useCallback((now: number): void => {
    const delta = Math.max(0, now - lastTime.current)
    lastTime.current = now
    if (!clockRunning.current) return
    const whole = Math.floor(fraction.current + delta)
    fraction.current = fraction.current + delta - whole
    if (whole < 1) return
    const current = stateRef.current
    const next = advanceGame(current, whole)
    if (next !== current) { stateRef.current = next; setState(next) }
  }, [])

  const commit = useCallback((next: GameState, now: number): void => {
    stateRef.current = next
    setState(next)
    lastTime.current = now
    clockRunning.current = next.started && !isWon(next) && !pausedRef.current && !document.hidden
    if (isWon(next)) clockRunning.current = false
  }, [])

  useEffect(() => {
    let frame = 0
    const tick = (now: number): void => {
      flushClock(now)
      frame = requestAnimationFrame(tick)
    }
    const visibilityChanged = (): void => {
      const now = performance.now()
      flushClock(now)
      lastTime.current = now
      clockRunning.current = !document.hidden && !pausedRef.current && stateRef.current.started && !isWon(stateRef.current)
    }
    document.addEventListener('visibilitychange', visibilityChanged)
    frame = requestAnimationFrame(tick)
    return () => { cancelAnimationFrame(frame); document.removeEventListener('visibilitychange', visibilityChanged) }
  }, [flushClock])

  const start = useCallback((code: string): void => {
    const next = createGame(code)
    if (!next) return
    clear()
    pausedRef.current = false
    setPaused(false)
    fraction.current = 0
    bestAllowed.current = true
    commit(next, performance.now())
    setRevision((value) => value + 1)
    setStatus('')
  }, [clear, commit])

  const newGame = useCallback(() => start(newCode(stateRef.current.board.size)), [start])
  const restart = useCallback(() => start(stateRef.current.board.code), [start])
  const chooseSize = useCallback((size: BoardSize) => {
    if (size === stateRef.current.board.size) return
    savePreferredSize(size)
    start(newCode(size))
  }, [start])

  const activate = useCallback((index: number): void => {
    const now = performance.now()
    flushClock(now)
    const before = stateRef.current
    if (pausedRef.current) return
    const next = activateCard(before, index)
    if (next === before) return
    commit(next, now)
    if (next.moves > before.moves) announce(next.selection.kind === 'mismatch' ? 'No match. Cards close after a short pause.' : pairAnnouncement(next))
    if (!isWon(before) && isWon(next) && bestAllowed.current && isBoardSize(next.board.size)) {
      setBestScores((scores) => recordBest(next.board.size, next.moves, scores))
    }
  }, [announce, commit, flushClock])

  const loadBoard = useCallback((draft: string): void => {
    flushClock(performance.now())
    const board = parseBoardCode(draft.trim())
    const next = board ? createGame(board.code) : null
    if (!board || !next || !isBoardSize(board.size)) { setStatus('Invalid board code.'); announce('Invalid board code.'); return }
    savePreferredSize(board.size)
    start(board.code)
    setStatus(`Loaded board ${board.code}.`)
    announce(`Loaded board ${board.code}.`)
  }, [announce, flushClock, start])

  const importSnapshot = useCallback((text: string): void => {
    flushClock(performance.now())
    const next = decodeSnapshot(text)
    if (!next || !isBoardSize(next.board.size)) { setStatus('Invalid snapshot.'); announce('Invalid snapshot.'); return }
    clear()
    const complete = isWon(next)
    const willPause = !complete
    pausedRef.current = willPause
    setPaused(willPause)
    bestAllowed.current = !complete
    fraction.current = 0
    commit(next, performance.now())
    savePreferredSize(next.board.size)
    setRevision((value) => value + 1)
    const textStatus = complete ? 'Loaded completed snapshot.' : 'Loaded snapshot. Select Resume to continue.'
    setStatus(textStatus)
    announce(textStatus)
  }, [announce, clear, commit, flushClock])

  const exportSnapshot = useCallback((): string => {
    flushClock(performance.now())
    const current = stateRef.current
    if (current.selection.kind !== 'mismatch') return encodeSnapshot(current)
    const remainingMs = Math.max(1, Math.ceil(current.selection.remainingMs - fraction.current))
    return encodeSnapshot({ ...current, selection: { ...current.selection, remainingMs } })
  }, [flushClock])

  const resume = useCallback((): void => {
    pausedRef.current = false
    setPaused(false)
    lastTime.current = performance.now()
    clockRunning.current = !document.hidden && stateRef.current.started && !isWon(stateRef.current)
    setStatus('')
  }, [])

  return { state, bestScores, revision, paused, status, announcement: message, newGame, restart, chooseSize, activate, loadBoard, importSnapshot, exportSnapshot, resume, announce }
}

const COLORS = [
  ['Cyan', '#63E7FF'], ['Magenta', '#FF71D6'], ['Green', '#8BEA7D'], ['Yellow', '#FFE082'],
  ['Orange', '#FFB064'], ['Violet', '#B49AFF'], ['Rose', '#FF8296'], ['Ice', '#D9F3FF'],
] as const
const SHAPES = ['circle', 'square', 'triangle', 'diamond', 'star', 'hexagon', 'plus', 'chevron'] as const
const MARKERS = ['top', 'top-right', 'right', 'bottom-right', 'bottom', 'bottom-left', 'left', 'top-left'] as const
const DIRECTIONS = [
  [0, -40], [28.284, -28.284], [40, 0], [28.284, 28.284],
  [0, 40], [-28.284, 28.284], [-40, 0], [-28.284, -28.284],
] as const

export type ShapeName = (typeof SHAPES)[number]
export interface FaceData {
  name: string
  color: string
  shape: ShapeName
  outline: boolean
  markerX: number
  markerY: number
}

export function faceData(id: number): FaceData {
  const shape = SHAPES[id % 8] ?? SHAPES[0]
  const markerIndex = Math.floor(id / 8) % 8
  const color = COLORS[markerIndex] ?? COLORS[0]
  const marker = MARKERS[markerIndex] ?? MARKERS[0]
  const fill = id >= 64 ? 'outline' : 'solid'
  const direction = DIRECTIONS[markerIndex] ?? DIRECTIONS[0]
  return {
    name: `${color[0].toLowerCase()} ${fill} ${shape}, marker ${marker}`,
    color: color[1], shape, outline: id >= 64,
    markerX: 50 + direction[0], markerY: 50 + direction[1],
  }
}

export function starPoints(): string {
  return Array.from({ length: 10 }, (_, index) => {
    const radius = index % 2 === 0 ? 25 : 11
    const angle = -Math.PI / 2 + index * Math.PI / 5
    return `${50 + Math.cos(angle) * radius},${50 + Math.sin(angle) * radius}`
  }).join(' ')
}
