import { useCallback, useEffect, useLayoutEffect, useRef, useState, type KeyboardEvent } from 'react'
import { SELECTION_KIND, type GameState } from '../model.ts'
import { Card } from './Card.tsx'

interface BoardProps {
  state: GameState
  resetFocus: number
  onActivate(index: number): void
  onExposeFocus(focusBoard: () => void): void
}

export function Board({ state, resetFocus, onActivate, onExposeFocus }: BoardProps) {
  const { size } = state.board
  const scrollArea = useRef<HTMLDivElement>(null)
  const cardRefs = useRef<Array<HTMLButtonElement | null>>([])
  const focusPosition = useRef(0)
  const [focusIndex, setFocusIndex] = useState(0)
  const [areaWidth, setAreaWidth] = useState(0)
  const cardSize = Math.min(88, Math.max(44, (areaWidth - 12 - (size - 1) * 6) / size))
  const columns = `repeat(${size}, var(--card-size))`

  useLayoutEffect(() => {
    const area = scrollArea.current
    if (!area) return
    const resize = new ResizeObserver(() => setAreaWidth(area.clientWidth))
    resize.observe(area)
    setAreaWidth(area.clientWidth)
    return () => resize.disconnect()
  }, [])

  useEffect(() => {
    focusPosition.current = 0
    setFocusIndex(0)
  }, [resetFocus])

  useEffect(() => {
    onExposeFocus(() => cardRefs.current[focusPosition.current]?.focus())
  }, [onExposeFocus])

  const handleFocus = useCallback((index: number): void => {
    focusPosition.current = index
    setFocusIndex(index)
  }, [])

  const moveFocus = (event: KeyboardEvent<HTMLDivElement>): void => {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return
    const current = event.target instanceof HTMLButtonElement ? Number(event.target.value) : NaN
    if (!Number.isInteger(current)) return
    let destination = current
    if (event.key === 'ArrowLeft' && current % size > 0) destination -= 1
    else if (event.key === 'ArrowRight' && current % size < size - 1) destination += 1
    else if (event.key === 'ArrowUp' && current >= size) destination -= size
    else if (event.key === 'ArrowDown' && current < size * (size - 1)) destination += size
    else return
    event.preventDefault()
    if (destination !== current) cardRefs.current[destination]?.focus()
  }

  return (
    <div ref={scrollArea} className="board-scroll" onKeyDown={moveFocus}>
      <div className="board-grid" role="group" aria-label={`${size} by ${size} card board`} style={{ gridTemplateColumns: columns, '--card-size': `${cardSize}px` }}>
        {state.deck.map((faceId, index) => {
          const matched = state.matched.includes(index)
          const selected = state.selection.kind === SELECTION_KIND.one
            ? state.selection.index === index
            : state.selection.kind === SELECTION_KIND.mismatch && (state.selection.first === index || state.selection.second === index)
          return (
            <Card
              key={index}
              index={index}
              size={size}
              faceId={faceId}
              revealed={selected}
              matched={matched}
              tabIndex={focusIndex === index ? 0 : -1}
              onFocus={() => handleFocus(index)}
              onRef={(node) => { cardRefs.current[index] = node }}
              onActivate={() => onActivate(index)}
            />
          )
        })}
      </div>
    </div>
  )
}
import { faceData } from './face.ts'
import { Face } from './Face.tsx'

interface CardProps {
  index: number
  size: number
  faceId: number
  revealed: boolean
  matched: boolean
  tabIndex: 0 | -1
  onFocus(): void
  onRef(node: HTMLButtonElement | null): void
  onActivate(): void
}

export function Card({ index, size, faceId, revealed, matched, tabIndex, onFocus, onRef, onActivate }: CardProps) {
  const row = Math.floor(index / size) + 1
  const column = index % size + 1
  const state = matched ? 'matched' : revealed ? 'revealed' : 'closed'
  const label = revealed || matched
    ? `Row ${row}, column ${column}, ${faceData(faceId).name}, ${state}`
    : `Row ${row}, column ${column}, closed`

  return (
    <button
      ref={onRef}
      type="button"
      className={`card-button${revealed || matched ? ' is-revealed' : ''}${matched ? ' is-matched' : ''}`}
      aria-label={label}
      aria-pressed={revealed || matched}
      aria-disabled={matched || undefined}
      tabIndex={tabIndex}
      onFocus={onFocus}
      onClick={onActivate}
    >
      {revealed || matched ? <Face faceId={faceId} /> : <BackFace />}
      {matched && <span className="match-check" aria-hidden="true">✓</span>}
    </button>
  )
}

function BackFace() {
  return (
    <svg aria-hidden="true" focusable="false" className="back-art" viewBox="0 0 100 100">
      <polygon points="50,27 73,50 50,73 27,50" fill="none" stroke="#757C9A" strokeWidth="4" />
    </svg>
  )
}
import { faceData, starPoints } from './face.ts'

interface FaceProps { faceId: number }

export function Face({ faceId }: FaceProps) {
  const face = faceData(faceId)
  const line = face.outline ? face.color : undefined
  const fill = face.outline ? 'none' : face.color
  const style = { fill, stroke: line, strokeWidth: face.outline ? 5 : undefined, strokeLinejoin: 'round' as const }
  return (
    <svg aria-hidden="true" focusable="false" className="face-art" viewBox="0 0 100 100">
      {face.shape === 'circle' && <circle cx="50" cy="50" r="25" {...style} />}
      {face.shape === 'square' && <rect x="25" y="25" width="50" height="50" {...style} />}
      {face.shape === 'triangle' && <polygon points="50,25 75,75 25,75" {...style} />}
      {face.shape === 'diamond' && <polygon points="50,25 75,50 50,75 25,50" {...style} />}
      {face.shape === 'star' && <polygon points={starPoints()} {...style} />}
      {face.shape === 'hexagon' && <polygon points="37.5,25 62.5,25 75,50 62.5,75 37.5,75 25,50" {...style} />}
      {face.shape === 'plus' && <path d="M42 25h16v17h17v16H58v17H42V58H25V42h17z" {...style} />}
      {face.shape === 'chevron' && <polygon points="25,25 75,50 25,75 25,59 54,50 25,41" {...style} />}
      <circle cx={face.markerX} cy={face.markerY} r="5" fill={face.color} stroke="#111625" strokeWidth="3" />
    </svg>
  )
}
import { useCallback, useEffect, useRef, useState } from 'react'

export function useAnnouncements(): { message: string; announce: (text: string) => void; clear: () => void } {
  const [message, setMessage] = useState('')
  const queue = useRef<string[]>([])
  const timer = useRef<number | null>(null)

  const announce = useCallback((text: string) => {
    queue.current.push(text)
    if (timer.current !== null) return
    const showNext = (): void => {
      const next = queue.current.shift()
      if (next === undefined) { timer.current = null; return }
      setMessage('')
      timer.current = window.setTimeout(() => {
        setMessage(next)
        timer.current = window.setTimeout(() => {
          setMessage('')
          timer.current = window.setTimeout(showNext, 0)
        }, 150)
      }, 40)
    }
    showNext()
  }, [])

  const clear = useCallback((): void => {
    if (timer.current !== null) window.clearTimeout(timer.current)
    timer.current = null
    queue.current = []
    setMessage('')
  }, [])

  useEffect(() => () => {
    if (timer.current !== null) window.clearTimeout(timer.current)
  }, [])

  return { message, announce, clear }
}

import { useCallback, useEffect, useRef, useState } from 'react'
import { activateCard, advanceGame, createGame, formatElapsed, isWon } from '../game.ts'
import { isBoardSize, MAX_SEED, parseBoardCode, type BoardSize } from '../board.ts'
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts'
import type { GameState } from '../model.ts'
import { recordBest, readBestScores, readPreferredSize, savePreferredSize, type BestScores } from './storage.ts'
import { useAnnouncements } from './useAnnouncements.ts'

function newCode(size: BoardSize, previousSeed?: number): string {
  const values = new Uint32Array(1)
  let seed: number
  try {
    seed = typeof crypto !== 'undefined'
      ? (crypto.getRandomValues(values), (values[0] ?? 0) % MAX_SEED + 1)
      : Math.floor(Math.random() * MAX_SEED) + 1
  } catch {
    seed = Math.floor(Math.random() * MAX_SEED) + 1
  }
  if (seed === previousSeed) seed = seed === MAX_SEED ? 1 : seed + 1
  return `np1-${size}-${seed}`
}

function initialGame(): GameState {
  const size = readPreferredSize()
  const game = createGame(newCode(size))
  if (!game) throw new Error('Unable to create a supported board')
  return game
}

function pairAnnouncement(state: GameState): string {
  if (isWon(state)) return `Pair found. All pairs found in ${state.moves} moves and ${formatElapsed(state.elapsedMs)}.`
  const pairs = state.matched.length / 2
  return pairs === 1 ? 'Pair found. 1 pair matched.' : `Pair found. ${pairs} pairs matched.`
}

export interface Session {
  state: GameState
  bestScores: BestScores
  revision: number
  paused: boolean
  status: string
  announcement: string
  newGame(): void
  restart(): void
  chooseSize(size: BoardSize): void
  activate(index: number): void
  loadBoard(code: string): void
  importSnapshot(text: string): void
  exportSnapshot(): string
  resume(): void
  announce(text: string): void
}

export function useSession(): Session {
  const [state, setState] = useState(initialGame)
  const stateRef = useRef(state)
  const [bestScores, setBestScores] = useState<BestScores>(readBestScores)
  const [revision, setRevision] = useState(0)
  const [paused, setPaused] = useState(false)
  const pausedRef = useRef(false)
  const [status, setStatus] = useState('')
  const { message, announce, clear } = useAnnouncements()
  const bestAllowed = useRef(true)
  const lastTime = useRef(performance.now())
  const pendingTime = useRef(0)
  const clockRunning = useRef(false)

  const flushClock = useCallback((now: number): void => {
    const delta = Math.max(0, now - lastTime.current)
    lastTime.current = now
    if (!clockRunning.current) return
    pendingTime.current += delta
    const current = stateRef.current
    const mismatchLimit = current.selection.kind === 'mismatch'
      ? current.selection.remainingMs - pendingTime.current
      : Number.POSITIVE_INFINITY
    if (pendingTime.current < Math.max(1, Math.min(250, mismatchLimit))) return
    const whole = Math.floor(pendingTime.current)
    pendingTime.current -= whole
    if (whole < 1) return
    const next = advanceGame(current, whole)
    if (next === current) return
    stateRef.current = next
    const secondChanged = Math.floor(next.elapsedMs / 1_000) !== Math.floor(current.elapsedMs / 1_000)
    const mismatchClosed = current.selection.kind === 'mismatch' && next.selection.kind !== 'mismatch'
    if (secondChanged || mismatchClosed) setState(next)
  }, [])

  const commit = useCallback((next: GameState, now: number): void => {
    stateRef.current = next
    setState(next)
    lastTime.current = now
    clockRunning.current = next.started && !isWon(next) && !pausedRef.current && !document.hidden
    if (isWon(next)) clockRunning.current = false
  }, [])

  useEffect(() => {
    let frame = 0
    const tick = (now: number): void => {
      flushClock(now)
      frame = requestAnimationFrame(tick)
    }
    const visibilityChanged = (): void => {
      const now = performance.now()
      flushClock(now)
      lastTime.current = now
      clockRunning.current = !document.hidden && !pausedRef.current && stateRef.current.started && !isWon(stateRef.current)
    }
    document.addEventListener('visibilitychange', visibilityChanged)
    frame = requestAnimationFrame(tick)
    return () => { cancelAnimationFrame(frame); document.removeEventListener('visibilitychange', visibilityChanged) }
  }, [flushClock])

  const start = useCallback((code: string): void => {
    const next = createGame(code)
    if (!next) return
    clear()
    pausedRef.current = false
    setPaused(false)
    pendingTime.current = 0
    bestAllowed.current = true
    commit(next, performance.now())
    setRevision((value) => value + 1)
    setStatus('')
  }, [clear, commit])

