export function startMismatchTimer(delayMs: number, onElapsed: () => void): number {
  return window.setTimeout(onElapsed, Math.max(1, Math.ceil(delayMs)))
}

export function cancelMismatchTimer(timer: number | null): void {
  if (timer !== null) window.clearTimeout(timer)
}
import { useCallback, useEffect, useRef, useState } from 'react'
import { activateCard, createGame, isWon } from '../game.ts'
import { isBoardSize, parseBoardCode, type BoardSize } from '../board.ts'
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts'
import { SELECTION_KIND, type GameState } from '../model.ts'
import { advanceActiveTime } from './clock.ts'
import { freshBoardCode, initialGame } from './deals.ts'
import { recordBest, readBestScores, savePreferredSize, type BestScores } from './storage.ts'
import { pairAnnouncement } from './turnMessages.ts'
import { useAnnouncements } from './useAnnouncements.ts'
import { cancelMismatchTimer, startMismatchTimer } from './mismatchTimer.ts'

export interface Session {
  state: GameState
  bestScores: BestScores
  revision: number
  paused: boolean
  celebrate: boolean
  status: string
  announcement: string
  newGame(): void
  restart(): void
  chooseSize(size: BoardSize): void
  activate(index: number): void
  loadBoard(code: string): void
  importSnapshot(text: string): void
  exportSnapshot(): string
  resume(): void
  announce(text: string): void
}

export function useSession(): Session {
  const [state, setState] = useState(initialGame)
  const stateRef = useRef(state)
  const [bestScores, setBestScores] = useState<BestScores>(readBestScores)
  const [revision, setRevision] = useState(0)
  const [paused, setPaused] = useState(false)
  const [celebrate, setCelebrate] = useState(false)
  const pausedRef = useRef(false)
  const [status, setStatus] = useState('')
  const { message, announce, clear } = useAnnouncements()
  const bestAllowed = useRef(true)
  const lastTime = useRef(performance.now())
  const elapsedRemainder = useRef(0)
  const mismatchRemainder = useRef(0)
  const mismatchTimer = useRef<number | null>(null)
  const clockRunning = useRef(false)

  const clearMismatchTimer = useCallback((): void => {
    cancelMismatchTimer(mismatchTimer.current)
    mismatchTimer.current = null
  }, [])

  const flushClock = useCallback((now: number, force = false): void => {
    const delta = Math.max(0, now - lastTime.current)
    lastTime.current = now
    if (!clockRunning.current) return
    elapsedRemainder.current += delta
    const current = stateRef.current
    if (current.selection.kind === SELECTION_KIND.mismatch) mismatchRemainder.current += delta
    const mismatchLimit = current.selection.kind === SELECTION_KIND.mismatch
      ? current.selection.remainingMs - mismatchRemainder.current
      : Number.POSITIVE_INFINITY
    if (!force && elapsedRemainder.current < Math.max(1, Math.min(250, mismatchLimit))) return
    const elapsed = Math.floor(elapsedRemainder.current)
    const mismatch = Math.floor(mismatchRemainder.current)
    elapsedRemainder.current -= elapsed
    mismatchRemainder.current -= mismatch
    if (elapsed < 1 && mismatch < 1) return
    const next = advanceActiveTime(current, elapsed, mismatch)
    if (next === current) return
    stateRef.current = next
    const secondChanged = Math.floor(next.elapsedMs / 1_000) !== Math.floor(current.elapsedMs / 1_000)
    const mismatchClosed = current.selection.kind === 'mismatch' && next.selection.kind !== 'mismatch'
    if (secondChanged || mismatchClosed) setState(next)
    if (mismatchClosed) {
      mismatchRemainder.current = 0
      clearMismatchTimer()
    }
  }, [clearMismatchTimer])

  const scheduleMismatchTimer = useCallback((): void => {
    clearMismatchTimer()
    const current = stateRef.current
    if (current.selection.kind !== SELECTION_KIND.mismatch || !clockRunning.current || pausedRef.current || document.hidden) return
    const remaining = current.selection.remainingMs - mismatchRemainder.current
    mismatchTimer.current = startMismatchTimer(remaining, () => {
      mismatchTimer.current = null
      flushClock(performance.now(), true)
    })
  }, [clearMismatchTimer, flushClock])

  const commit = useCallback((next: GameState, now: number): void => {
    stateRef.current = next
    setState(next)
    lastTime.current = now
    clockRunning.current = next.started && !isWon(next) && !pausedRef.current && !document.hidden
    if (isWon(next)) clockRunning.current = false
  }, [])

  useEffect(() => {
    let frame = 0
    const tick = (now: number): void => {
      flushClock(now)
      frame = requestAnimationFrame(tick)
    }
    const visibilityChanged = (): void => {
      const now = performance.now()
      flushClock(now, true)
      lastTime.current = now
      clockRunning.current = !document.hidden && !pausedRef.current && stateRef.current.started && !isWon(stateRef.current)
      if (document.hidden) clearMismatchTimer()
      else scheduleMismatchTimer()
    }
    document.addEventListener('visibilitychange', visibilityChanged)
    frame = requestAnimationFrame(tick)
    return () => { cancelAnimationFrame(frame); document.removeEventListener('visibilitychange', visibilityChanged); clearMismatchTimer() }
  }, [clearMismatchTimer, flushClock, scheduleMismatchTimer])

  const start = useCallback((code: string): void => {
    const next = createGame(code)
    if (!next) return
    clearMismatchTimer()
    clear()
    pausedRef.current = false
    setPaused(false)
    setCelebrate(false)
    elapsedRemainder.current = 0
    mismatchRemainder.current = 0
    bestAllowed.current = true
    commit(next, performance.now())
    setRevision((value) => value + 1)
    setStatus('')
  }, [clear, clearMismatchTimer, commit])

  const newGame = useCallback(() => {
    const board = stateRef.current.board
    if (isBoardSize(board.size)) start(freshBoardCode(board.size, board.seed))
  }, [start])
  const restart = useCallback(() => start(stateRef.current.board.code), [start])
  const chooseSize = useCallback((size: BoardSize) => {
    if (size === stateRef.current.board.size) return
    savePreferredSize(size)
    start(freshBoardCode(size, stateRef.current.board.seed))
  }, [start])

  const activate = useCallback((index: number): void => {
    const now = performance.now()
    flushClock(now, true)
    const before = stateRef.current
    if (pausedRef.current) return
    const next = activateCard(before, index)
    if (next === before) return
    commit(next, now)
    if (before.selection.kind !== SELECTION_KIND.mismatch && next.selection.kind === SELECTION_KIND.mismatch) {
      mismatchRemainder.current = 0
      scheduleMismatchTimer()
    }
    if (before.selection.kind === 'one') announce(next.selection.kind === 'mismatch' ? 'No match. Cards close after a short pause.' : pairAnnouncement(next))
    const finishedSize = next.board.size
    if (!isWon(before) && isWon(next) && bestAllowed.current && isBoardSize(finishedSize)) {
      setBestScores((scores) => recordBest(finishedSize, next.moves, scores))
    }
    if (!isWon(before) && isWon(next)) setCelebrate(true)
  }, [announce, commit, flushClock, scheduleMismatchTimer])

  const loadBoard = useCallback((draft: string): void => {
    flushClock(performance.now(), true)
    const board = parseBoardCode(draft.trim())
    const next = board ? createGame(board.code) : null
    if (!board || !next || !isBoardSize(board.size)) { setStatus('Invalid board code.'); announce('Invalid board code.'); return }
    savePreferredSize(board.size)
    start(board.code)
    setStatus(`Loaded board ${board.code}.`)
    announce(`Loaded board ${board.code}.`)
  }, [announce, flushClock, start])

  const importSnapshot = useCallback((text: string): void => {
    flushClock(performance.now(), true)
    const next = decodeSnapshot(text)
    if (!next || !isBoardSize(next.board.size)) { setStatus('Invalid snapshot.'); announce('Invalid snapshot.'); return }
    clear()
    clearMismatchTimer()
    const complete = isWon(next)
    const willPause = !complete
    pausedRef.current = willPause
    setPaused(willPause)
    bestAllowed.current = !complete
    setCelebrate(false)
    elapsedRemainder.current = 0
    mismatchRemainder.current = 0
    commit(next, performance.now())
    savePreferredSize(next.board.size)
    setRevision((value) => value + 1)
    const textStatus = complete ? 'Loaded completed snapshot.' : 'Loaded snapshot. Select Resume to continue.'
    setStatus(textStatus)
    announce(textStatus)
  }, [announce, clear, clearMismatchTimer, commit, flushClock])

  const exportSnapshot = useCallback((): string => {
    flushClock(performance.now(), true)
    const current = stateRef.current
    if (current.selection.kind !== 'mismatch') return encodeSnapshot(current)
    const remainingMs = Math.max(1, Math.ceil(current.selection.remainingMs - mismatchRemainder.current))
    return encodeSnapshot({ ...current, selection: { ...current.selection, remainingMs } })
  }, [flushClock])

  const resume = useCallback((): void => {
    pausedRef.current = false
    setPaused(false)
    lastTime.current = performance.now()
    clockRunning.current = !document.hidden && stateRef.current.started && !isWon(stateRef.current)
    scheduleMismatchTimer()
    setStatus('')
  }, [scheduleMismatchTimer])

  return { state, bestScores, revision, paused, celebrate, status, announcement: message, newGame, restart, chooseSize, activate, loadBoard, importSnapshot, exportSnapshot, resume, announce }
}

import { useCallback, useEffect, useRef, type Dispatch, type MutableRefObject, type SetStateAction } from 'react'
import { isWon } from '../game.ts'
import { SELECTION_KIND, type GameState } from '../model.ts'
import { advanceActiveTime } from './clock.ts'
import { cancelMismatchTimer, startMismatchTimer } from './mismatchTimer.ts'

export interface ActiveClock {
  commit(state: GameState, now: number): void
  replace(state: GameState): void
  flush(now: number, force?: boolean): void
  beginMismatch(): void
  resume(): void
}

export function useActiveClock(
  stateRef: MutableRefObject<GameState>,
  setState: Dispatch<SetStateAction<GameState>>,
  pausedRef: MutableRefObject<boolean>,
): ActiveClock {
  const lastTime = useRef(performance.now())
  const elapsedRemainder = useRef(0)
  const mismatchRemainder = useRef(0)
  const mismatchTimer = useRef<number | null>(null)
  const clockRunning = useRef(false)

  const clearTimer = useCallback((): void => {
    cancelMismatchTimer(mismatchTimer.current)
    mismatchTimer.current = null
  }, [])

  const flush = useCallback((now: number, force = false): void => {
    const delta = Math.max(0, now - lastTime.current)
    lastTime.current = now
    if (!clockRunning.current) return
    elapsedRemainder.current += delta
    const current = stateRef.current
    if (current.selection.kind === SELECTION_KIND.mismatch) mismatchRemainder.current += delta
    const mismatchLimit = current.selection.kind === SELECTION_KIND.mismatch
      ? current.selection.remainingMs - mismatchRemainder.current
      : Number.POSITIVE_INFINITY
    if (!force && elapsedRemainder.current < Math.max(1, Math.min(250, mismatchLimit))) return
    const elapsed = Math.floor(elapsedRemainder.current)
    const mismatch = Math.floor(mismatchRemainder.current)
    elapsedRemainder.current -= elapsed
    mismatchRemainder.current -= mismatch
    if (elapsed < 1 && mismatch < 1) return
    const next = advanceActiveTime(current, elapsed, mismatch)
    if (next === current) return
    stateRef.current = next
    const secondChanged = Math.floor(next.elapsedMs / 1_000) !== Math.floor(current.elapsedMs / 1_000)
    const mismatchClosed = current.selection.kind === SELECTION_KIND.mismatch && next.selection.kind !== SELECTION_KIND.mismatch
    if (secondChanged || mismatchClosed) setState(next)
    if (mismatchClosed) {
      mismatchRemainder.current = 0
      clearTimer()
    }
  }, [clearTimer, setState, stateRef])

  const scheduleTimer = useCallback((): void => {
    clearTimer()
    const current = stateRef.current
    if (current.selection.kind !== SELECTION_KIND.mismatch || !clockRunning.current || pausedRef.current || document.hidden) return
    const remaining = current.selection.remainingMs - mismatchRemainder.current
    mismatchTimer.current = startMismatchTimer(remaining, () => {
      mismatchTimer.current = null
      flush(performance.now(), true)
    })
  }, [clearTimer, flush, pausedRef, stateRef])

  const commit = useCallback((next: GameState, now: number): void => {
    stateRef.current = next
    setState(next)
    lastTime.current = now
    clockRunning.current = next.started && !isWon(next) && !pausedRef.current && !document.hidden
    if (isWon(next)) clockRunning.current = false
  }, [pausedRef, setState, stateRef])

  const replace = useCallback((next: GameState): void => {
    clearTimer()
    elapsedRemainder.current = 0
    mismatchRemainder.current = 0
    commit(next, performance.now())
  }, [clearTimer, commit])

  const beginMismatch = useCallback((): void => {
    mismatchRemainder.current = 0
    scheduleTimer()
  }, [scheduleTimer])

  const resume = useCallback((): void => {
    lastTime.current = performance.now()
    clockRunning.current = !document.hidden && stateRef.current.started && !isWon(stateRef.current)
    scheduleTimer()
  }, [scheduleTimer, stateRef])

  useEffect(() => {
    let frame = 0
    const tick = (now: number): void => {
      flush(now)
      frame = requestAnimationFrame(tick)
    }
    const visibilityChanged = (): void => {
      const now = performance.now()
      flush(now, true)
      lastTime.current = now
      clockRunning.current = !document.hidden && !pausedRef.current && stateRef.current.started && !isWon(stateRef.current)
      if (document.hidden) clearTimer()
      else scheduleTimer()
    }
    document.addEventListener('visibilitychange', visibilityChanged)
    frame = requestAnimationFrame(tick)
    return () => { cancelAnimationFrame(frame); document.removeEventListener('visibilitychange', visibilityChanged); clearTimer() }
  }, [clearTimer, flush, pausedRef, scheduleTimer, stateRef])

  return { commit, replace, flush, beginMismatch, resume }
}
