const sourceFiles=(await Promise.all(['"'src','e2e','scripts'].map(files))).flat().filter(path=>/\\.tsx?"'$/u.test(path));
const oversize=[];
let maximum=0;
for(const path of sourceFiles){const count=(await readFile(path,'"'utf8')).split('\\n').length-1;maximum=Math.max(maximum,count);if(count>200)oversize.push({path,count})}
const html=await stat('dist/index.html');
console.log(JSON.stringify({distFiles:await readdir('dist'),htmlBytes:html.size,authoredTsFiles:sourceFiles.length,maximumTsLines:maximum,oversize}));
NODE"

